def apply_device_picker_document(doc: dict, language: str) -> None:
    title, description, optional, help_text = TEXT[language]
    for scope in ("config", "options"):
        steps = doc.get(scope, {}).get("step", {})
        if "area_settings" not in steps:
            continue
        menu = steps["area_settings"]["menu_options"]
        menu.pop("climate", None)
        menu.pop("pid", None)
        menu["area_devices"] = title
        steps["area_devices"]["title"] = title
        # Reuse the localized existing area selector label without creating a
        # second source vocabulary. The next page explains the saved hierarchy.
        steps["area_devices"]["description"] = steps["area_devices"]["data"]["area_devices_area"]
        picker = steps["select_devices"]
        picker["title"] = title
        picker["description"] = description
        picker.setdefault("data", {})["configure_device_sources"] = optional
        picker.setdefault("data_description", {})["configure_device_sources"] = help_text
        picker["data_description"]["selected_devices"] = description
        steps["device_menu"]["description"] = help_text
